const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert');
const request = require('supertest');
const { installMock, resetMockDb } = require('./mockDb');

process.env.JWT_SECRET = process.env.JWT_SECRET || 'test-secret-key';
installMock();
const app = require('../src/app');

describe('Task Manager Application Tests', () => {
  beforeEach(() => resetMockDb());

  it('serves login page', async () => {
    const res = await request(app).get('/login');
    assert.strictEqual(res.status, 200);
  });

  it('rejects auth endpoint without token', async () => {
    const res = await request(app).get('/api/auth/me');
    assert.strictEqual(res.status, 401);
  });

  it('signs up and logs in securely', async () => {
    const signup = await request(app).post('/api/auth/signup').send({ email: 'alice@example.com', password: 'password1234' });
    assert.strictEqual(signup.status, 201);
    assert.ok(signup.body.user);
    assert.ok(!signup.body.token);

    const login = await request(app).post('/api/auth/login').send({ email: 'alice@example.com', password: 'password1234' });
    assert.strictEqual(login.status, 200);
    assert.ok(!login.body.token);
    assert.ok(login.headers['set-cookie'].some(c => c.includes('HttpOnly')));
  });

  it('enforces task isolation', async () => {
    const alice = await request(app).post('/api/auth/signup').send({ email: 'alice@example.com', password: 'password1234' });
    const bob = await request(app).post('/api/auth/signup').send({ email: 'bob@example.com', password: 'password1234' });

    const task = await request(app).post('/api/tasks').set('Authorization', `Bearer ${alice.headers['set-cookie'][0].split(';')[0].split('=')[1]}`).send({ title: 'Secret', status: 'to do' });
    const view = await request(app).get(`/api/tasks/${task.body.id}`).set('Authorization', `Bearer ${bob.headers['set-cookie'][0].split(';')[0].split('=')[1]}`);
    assert.strictEqual(view.status, 404);
  });
});

